-- IT Store (ITAM) — create an empty database
-- Generated by `npm run schema:empty` (server/schema-empty.js) from server/schema.sql + addColumn() migrations + bootstrap().
-- Usage:  sqlite3 data/it_storage.db < docs/create-empty-db.sql   (target file must not exist yet)
-- Contains no users: the server creates admin / Admin@1234 on first start (server/bootstrap.js).

PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

-- TABLES

CREATE TABLE access_logs (
  id         INTEGER PRIMARY KEY,
  user_id    INTEGER,
  username   TEXT,
  event      TEXT NOT NULL,
  ip         TEXT,
  user_agent TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE asset_transactions (
  id            INTEGER PRIMARY KEY,
  asset_id      INTEGER NOT NULL REFERENCES assets(id),
  action        TEXT NOT NULL,
  from_status   TEXT,
  to_status     TEXT,
  person_id     INTEGER REFERENCES people(id),
  department_id INTEGER REFERENCES departments(id),
  location_id   INTEGER REFERENCES locations(id),
  due_date      TEXT,
  note          TEXT,
  evidence_path TEXT,
  cost          REAL,
  performed_by  INTEGER REFERENCES users(id),
  doc_id        INTEGER REFERENCES documents(id),
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE assets (
  id               INTEGER PRIMARY KEY,
  asset_tag        TEXT UNIQUE NOT NULL,
  category_id      INTEGER NOT NULL REFERENCES categories(id),
  name             TEXT NOT NULL,
  brand            TEXT,
  model            TEXT,
  serial_no        TEXT,
  specs            TEXT,
  status           TEXT NOT NULL DEFAULT 'available'
                   CHECK (status IN ('available','borrowed','issued','repair','pending_disposal','scrapped')),
  location_id      INTEGER REFERENCES locations(id),
  holder_person_id INTEGER REFERENCES people(id),
  department_id    INTEGER REFERENCES departments(id),
  due_date         TEXT,
  purchase_date    TEXT,
  purchase_price   REAL,
  po_number        TEXT,
  invoice_number   TEXT,
  vendor_id        INTEGER REFERENCES vendors(id),
  warranty_expiry  TEXT,
  received_date    TEXT,
  image_path       TEXT,
  notes            TEXT,
  created_at       TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at       TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at       TEXT
);

CREATE TABLE audit_logs (
  id         INTEGER PRIMARY KEY,
  user_id    INTEGER,
  username   TEXT,
  entity     TEXT NOT NULL,
  entity_id  INTEGER,
  action     TEXT NOT NULL,
  before_json TEXT,
  after_json  TEXT,
  ip         TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE categories (
  id         INTEGER PRIMARY KEY,
  name       TEXT NOT NULL,
  kind       TEXT NOT NULL CHECK (kind IN ('asset','consumable')),
  prefix     TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at TEXT
);

CREATE TABLE consumables (
  id            INTEGER PRIMARY KEY,
  sku           TEXT UNIQUE NOT NULL,
  category_id   INTEGER NOT NULL REFERENCES categories(id),
  name          TEXT NOT NULL,
  unit          TEXT NOT NULL DEFAULT 'ชิ้น',
  qty_on_hand   INTEGER NOT NULL DEFAULT 0 CHECK (qty_on_hand >= 0),
  reorder_point INTEGER NOT NULL DEFAULT 0,
  location_id   INTEGER REFERENCES locations(id),
  unit_cost     REAL,
  vendor_id     INTEGER REFERENCES vendors(id),
  notes         TEXT,
  image_path    TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at    TEXT
);

CREATE TABLE departments (
  id         INTEGER PRIMARY KEY,
  name       TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at TEXT
);

CREATE TABLE documents (
  id            INTEGER PRIMARY KEY,
  doc_no        TEXT UNIQUE NOT NULL,
  type          TEXT NOT NULL CHECK (type IN ('receive','issue')),
  doc_date      TEXT NOT NULL,
  mode          TEXT,
  person_id     INTEGER REFERENCES people(id),
  department_id INTEGER REFERENCES departments(id),
  location_id   INTEGER REFERENCES locations(id),
  vendor_id     INTEGER REFERENCES vendors(id),
  po_number     TEXT,
  invoice_number TEXT,
  due_date      TEXT,
  note          TEXT,
  created_by    INTEGER REFERENCES users(id),
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE locations (
  id         INTEGER PRIMARY KEY,
  name       TEXT NOT NULL,
  branch     TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at TEXT
);

CREATE TABLE people (
  id            INTEGER PRIMARY KEY,
  emp_code      TEXT,
  name          TEXT NOT NULL,
  department_id INTEGER REFERENCES departments(id),
  email         TEXT,
  phone         TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at    TEXT
);

CREATE TABLE permissions (
  key   TEXT PRIMARY KEY,
  name  TEXT NOT NULL,
  grp   TEXT NOT NULL
);

CREATE TABLE role_permissions (
  role_id  INTEGER NOT NULL REFERENCES roles(id),
  perm_key TEXT NOT NULL REFERENCES permissions(key),
  PRIMARY KEY (role_id, perm_key)
);

CREATE TABLE roles (
  id          INTEGER PRIMARY KEY,
  key         TEXT UNIQUE NOT NULL,
  name        TEXT NOT NULL,
  description TEXT,
  is_system   INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE sessions (
  id          TEXT PRIMARY KEY,
  user_id     INTEGER NOT NULL REFERENCES users(id),
  ip          TEXT,
  user_agent  TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  last_seen   TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE stock_count_scans (
  id          INTEGER PRIMARY KEY,
  count_id    INTEGER NOT NULL REFERENCES stock_counts(id),
  asset_id    INTEGER REFERENCES assets(id),
  raw_code    TEXT NOT NULL,
  scanned_by  INTEGER REFERENCES users(id),
  scanned_at  TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (count_id, raw_code)
);

CREATE TABLE stock_counts (
  id          INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  location_id INTEGER REFERENCES locations(id),
  status      TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed')),
  created_by  INTEGER REFERENCES users(id),
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  closed_at   TEXT
);

CREATE TABLE stock_movements (
  id             INTEGER PRIMARY KEY,
  consumable_id  INTEGER NOT NULL REFERENCES consumables(id),
  type           TEXT NOT NULL CHECK (type IN ('in','out','adjust')),
  qty            INTEGER NOT NULL,
  balance_after  INTEGER NOT NULL,
  person_id      INTEGER REFERENCES people(id),
  department_id  INTEGER REFERENCES departments(id),
  unit_cost      REAL,
  received_date  TEXT,
  note           TEXT,
  performed_by   INTEGER REFERENCES users(id),
  doc_id         INTEGER REFERENCES documents(id),
  created_at     TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE users (
  id              INTEGER PRIMARY KEY,
  username        TEXT UNIQUE NOT NULL COLLATE NOCASE,
  password_hash   TEXT NOT NULL,
  full_name       TEXT NOT NULL,
  email           TEXT,
  role_id         INTEGER NOT NULL REFERENCES roles(id),
  is_active       INTEGER NOT NULL DEFAULT 1,
  failed_attempts INTEGER NOT NULL DEFAULT 0,
  locked_until    TEXT,
  last_login_at   TEXT,
  password_changed_at TEXT,
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at      TEXT
);

CREATE TABLE vendors (
  id         INTEGER PRIMARY KEY,
  name       TEXT NOT NULL,
  contact    TEXT,
  phone      TEXT,
  email      TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  deleted_at TEXT
);

-- INDEXES

CREATE INDEX idx_access_created ON access_logs(created_at);
CREATE INDEX idx_assets_serial ON assets(serial_no);
CREATE INDEX idx_assets_status ON assets(status) WHERE deleted_at IS NULL;
CREATE INDEX idx_atx_asset ON asset_transactions(asset_id, created_at);
CREATE INDEX idx_atx_doc ON asset_transactions(doc_id) WHERE doc_id IS NOT NULL;
CREATE INDEX idx_audit_created ON audit_logs(created_at);
CREATE INDEX idx_audit_entity ON audit_logs(entity, entity_id);
CREATE INDEX idx_docs_type ON documents(type, doc_date);
CREATE INDEX idx_sm_cons ON stock_movements(consumable_id, created_at);
CREATE INDEX idx_sm_doc ON stock_movements(doc_id) WHERE doc_id IS NOT NULL;

