-- TRIGGERS (append-only logs and history)

CREATE TRIGGER access_no_delete BEFORE DELETE ON access_logs
WHEN OLD.created_at > datetime('now', '-' || COALESCE((SELECT value FROM settings WHERE key = 'log_retention_days'), '3650') || ' days')
BEGIN SELECT RAISE(ABORT, 'access_logs is immutable'); END;

CREATE TRIGGER access_no_update BEFORE UPDATE ON access_logs
BEGIN SELECT RAISE(ABORT, 'access_logs is immutable'); END;

CREATE TRIGGER atx_no_delete BEFORE DELETE ON asset_transactions
BEGIN SELECT RAISE(ABORT, 'asset history is immutable'); END;

CREATE TRIGGER atx_no_update BEFORE UPDATE ON asset_transactions
BEGIN SELECT RAISE(ABORT, 'asset history is immutable'); END;

CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_logs
WHEN OLD.created_at > datetime('now', '-' || COALESCE((SELECT value FROM settings WHERE key = 'log_retention_days'), '3650') || ' days')
BEGIN SELECT RAISE(ABORT, 'audit_logs is immutable'); END;

CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_logs
BEGIN SELECT RAISE(ABORT, 'audit_logs is immutable'); END;

COMMIT;
PRAGMA foreign_keys = ON;
